// Evidence files live in IndexedDB, separate from small project records.
const evidenceDB=new Promise((resolve,reject)=>{const r=indexedDB.open('rumbo-evidence',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function evidenceStore(mode,action){const db=await evidenceDB;return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode),r=action(tx.objectStore('files'));let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const evidenceSection=document.createElement('section');evidenceSection.id='evidence';evidenceSection.innerHTML=`<h3>Evidencias</h3><p class="muted">Pruebas de gestión o culminación de esta tarea. Se guardan en este navegador y dispositivo.</p><div id="evidenceContent"></div>`;$('#form .dialogfoot').before(evidenceSection);
let evidenceTask=null,evidenceUrls=[];
function clearEvidenceURLs(){evidenceUrls.forEach(URL.revokeObjectURL);evidenceUrls=[]}
const oldOpen=open;open=function(type,id,status){oldOpen(type,id,status);evidenceTask=type==='task'?id:null;evidenceSection.hidden=type!=='task';clearEvidenceURLs();if(type==='task')showEvidence()};
async function showEvidence(){const taskId=evidenceTask,el=$('#evidenceContent');if(!taskId){el.innerHTML='<p class="muted">Guarda primero la tarea para añadir sus evidencias.</p>';return}el.innerHTML='<p class="muted">Cargando evidencias…</p>';try{const files=(await evidenceStore('readonly',s=>s.getAll())).filter(f=>f.taskId===taskId);if(evidenceTask!==taskId)return;clearEvidenceURLs();el.innerHTML=`<label>Tipo de prueba<select id="evidenceStage"><option>Gestión</option><option>Culminación</option></select></label><label class="uploadEvidence">＋ Adjuntar imagen, video o correo<input id="evidenceFile" type="file" multiple accept="image/*,video/*,.eml,.msg"></label><p class="muted">Hasta 100 MB por archivo. Los correos se descargan para abrirlos con tu aplicación de mail.</p><details><summary>Pegar un correo como evidencia</summary><label>Asunto<input id="mailSubject" maxlength="150" placeholder="Asunto del correo"></label><label>Contenido<textarea id="mailBody" rows="5" placeholder="Pega el remitente, fecha y mensaje"></textarea></label><button type="button" id="saveMail">Guardar correo</button></details><div id="evidenceList"></div><button type="button" id="downloadEvidence" ${files.length?'':'hidden'}>↓ Descargar todas las evidencias</button>`;
const list=$('#evidenceList');for(const f of files){const url=URL.createObjectURL(f.blob);evidenceUrls.push(url);const card=document.createElement('article');card.className='evidenceCard';card.innerHTML=`<div class="sectionhead"><b>${esc(f.name)}</b><button type="button" data-remove-file="${f.id}" aria-label="Eliminar evidencia">✕</button></div><small>${esc(f.stage)} · ${new Date(f.created).toLocaleString('es')} · ${(f.blob.size/1024/1024).toFixed(2)} MB</small>`;if(f.type.startsWith('image/')&&f.type!=='image/svg+xml'){const img=document.createElement('img');img.src=url;img.alt=f.name;card.append(img)}else if(f.type.startsWith('video/')){const video=document.createElement('video');video.src=url;video.controls=true;video.preload='metadata';card.append(video)}else if(f.type==='text/plain'){const pre=document.createElement('pre');pre.textContent=await f.blob.text();card.append(pre)}const a=document.createElement('a');a.href=url;a.download=f.name;a.textContent='↓ Descargar archivo';card.append(a);list.append(card)}if(!files.length)list.innerHTML='<p class="empty">Esta tarea todavía no tiene evidencias.</p>';
$('#evidenceFile').onchange=async e=>{const selectedFiles=Array.from(e.target.files);e.target.disabled=true;try{for(const f of selectedFiles){if(f.size>100*1024*1024)throw new Error('El archivo '+f.name+' supera los 100 MB.');if(!f.type.startsWith('image/')&&!f.type.startsWith('video/')&&!/\.(eml|msg)$/i.test(f.name))throw new Error('Formato no admitido: '+f.name);await evidenceStore('readwrite',s=>s.put({id:crypto.randomUUID(),taskId,stage:$('#evidenceStage').value,name:f.name,type:f.type,created:Date.now(),blob:f}))}toast('Evidencias guardadas');showEvidence();updateEvidenceCounts()}catch(err){toast(err.message||'No se pudo guardar el archivo');showEvidence()}};
$('#saveMail').onclick=async()=>{const subject=$('#mailSubject').value.trim(),body=$('#mailBody').value.trim();if(!subject||!body){toast('Completa el asunto y contenido del correo');return}try{await evidenceStore('readwrite',s=>s.put({id:crypto.randomUUID(),taskId,stage:$('#evidenceStage').value,name:subject+'.txt',type:'text/plain',created:Date.now(),blob:new Blob([subject+'\n\n'+body],{type:'text/plain'})}));toast('Correo guardado');showEvidence();updateEvidenceCounts()}catch{toast('No se pudo guardar el correo')}};
list.onclick=async e=>{const b=e.target.closest('[data-remove-file]');if(!b||!confirm('¿Eliminar esta evidencia?'))return;try{await evidenceStore('readwrite',s=>s.delete(b.dataset.removeFile));showEvidence();updateEvidenceCounts()}catch{toast('No se pudo eliminar la evidencia')}};$('#downloadEvidence').onclick=()=>{list.querySelectorAll('a[download]').forEach(a=>a.click());toast('Descarga iniciada; permite varias descargas si tu navegador lo solicita')};
}catch{el.innerHTML='<p role="alert">No se pudo acceder a las evidencias. Comprueba que el navegador permite el almacenamiento local.</p>'}}
async function updateEvidenceCounts(){try{const files=await evidenceStore('readonly',s=>s.getAll());document.querySelectorAll('.evidenceCount').forEach(e=>e.remove());$$('[data-task]').forEach(card=>{const count=files.filter(f=>f.taskId===card.dataset.task).length;if(count){const badge=document.createElement('div');badge.className='evidenceCount';badge.textContent='↳ '+count+' evidencia'+(count===1?'':'s');card.append(badge)}})}catch{}}
const originalRender=render;render=function(){originalRender();updateEvidenceCounts()};$('#modal').addEventListener('close',()=>{clearEvidenceURLs();evidenceTask=null});updateEvidenceCounts();

